-- changeset kaizen:223_seed_sgsi_documento splitStatements:false
-- Seed REAL: 286 obrigações documentais (cada uma ligada ao instrumento e, quando derivada
-- do plano, à tarefa 5W2H de origem). Idempotente (ON CONFLICT). Origem: SGSI/03_documento.sql.

ON CONFLICT (seed_key) DO NOTHING;

-- changeset kaizen:223b_sgsi_documento_atividade
-- Preenche 'atividade' (5W2H de origem) com o nome, para as obrigações derivadas do plano.
UPDATE sgsi_documento SET atividade = nome WHERE seed_key IS NOT NULL AND atividade IS NULL;
